    const boundedSide = bounded.container.querySelector<HTMLButtonElement>(`[data-slot='stepper-${pointerCase.side}']`)!;
    expect(boundedSide.disabled).toBe(pointerCase.disabled);
    fireEvent.mouseDown(boundedSide);
