        "parentId": { "type": ["string", "null"] },
        "hasChildren": { "type": "boolean" },
        "descriptorValues": { "type": "object", "maxProperties": 0 }
      }
    },
    "nonEmptyIds": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string", "minLength": 1 }
    },
    "levels": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "integer", "minimum": 0 }
    }
  }
